package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicLong;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.query.algebra.evaluation.ValueExprEvaluationException;
import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * A registered function called without arguments reads context rather than input (for example
 * {@code spif:currentTimeMillis()}). {@code ConstantOptimizer} folds it into a constant once per query, so the LMDB
 * pipeline plan cache must not replay the folded value of the first (cold) execution on later (warm) executions,
 * exactly as for {@code NOW()}.
 */
public class LmdbContextFunctionPlanReuseTest {

	private static final String TICK = "urn:test:lmdb-context-tick";

	private final Function tick = new TickFunction();

	@BeforeEach
	void registerFunction() {
		FunctionRegistry.getInstance().add(tick);
	}

	@AfterEach
	void unregisterFunction() {
		FunctionRegistry.getInstance().remove(tick);
	}

	@Test
	void zeroArgumentContextFunctionIsReevaluatedOnWarmExecutions(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			String query = "SELECT ?t { BIND(<" + TICK + ">() AS ?t) }";
			List<Long> ticks = new ArrayList<>();
			for (int i = 0; i < 3; i++) {
				ticks.add(evaluateSingle(conn, query, "t"));
			}
			assertTrue(ticks.get(0) < ticks.get(1) && ticks.get(1) < ticks.get(2),
					"every execution must read the context function afresh, got " + ticks);
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void zeroArgumentContextFunctionInFilterIsReevaluatedOnWarmExecutions(@TempDir File dataDir) {
		SailRepository repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			conn.add(vf.createIRI("urn:t:s1"), RDF.VALUE, vf.createLiteral(1L));
			conn.add(vf.createIRI("urn:t:s2"), RDF.VALUE, vf.createLiteral(2L));
			conn.add(vf.createIRI("urn:t:s3"), RDF.VALUE, vf.createLiteral(3L));
			String query = "SELECT (COUNT(?s) AS ?c) { ?s <" + RDF.VALUE + "> ?v FILTER(?v < <" + TICK + ">()) }";
			TickFunction.COUNTER.set(0);
			// the cold execution reads a small tick (count 0 or 1); warm executions must read larger ticks
			List<Long> counts = new ArrayList<>();
			for (int i = 0; i < 3; i++) {
				counts.add(evaluateSingle(conn, query, "c"));
			}
			assertTrue(counts.get(0) <= 1, "cold execution must see the first ticks, got " + counts);
			assertTrue(counts.get(0) < counts.get(1) && counts.get(1) <= counts.get(2),
					"warm executions must not reuse the cold execution's folded tick, got " + counts);
		} finally {
			repository.shutDown();
		}
	}

	private static long evaluateSingle(SailRepositoryConnection conn, String query, String name) {
		try (TupleQueryResult result = conn.prepareTupleQuery(query).evaluate()) {
			assertTrue(result.hasNext(), "one result row expected");
			BindingSet bindings = result.next();
			Value value = bindings.getValue(name);
			return assertInstanceOf(Literal.class, value, "?" + name + " must be bound").longValue();
		}
	}

	/** Deterministic stand-in for a clock: every call returns the next value of a counter. */
	private static final class TickFunction implements Function {

		private static final AtomicLong COUNTER = new AtomicLong();

		@Override
		public String getURI() {
			return TICK;
		}

		@Override
		public Value evaluate(ValueFactory valueFactory, Value... args) throws ValueExprEvaluationException {
			return valueFactory.createLiteral(COUNTER.incrementAndGet());
		}
	}
}
